head.script:
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    //Test step 1. 샘플실행 후 inputCalendar에 201512 값을 직접 입력 후 달력아이콘을 클릭한다.
    //1. After running the sample, type 201512 directly into inputCalendar and click the calendar icon.
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('wq_uuid_1_input').focus()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('wq_uuid_1_input').value = '201512'");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('wq_uuid_1_input').blur()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('wq_uuid_1_img').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 1. 입력한 값과 동일하게 달력아이콘의 값도 '12월2015년'으로 표기되어지고 focus도 12월로 보여진다. (이전에는 입력값과 상관없이 현재년월로 보여짐)
    //1. The value of the calendar icon will be marked as 'December 2015' and the focus will be displayed in December as well as the value entered.(Previously shown as the current month regardless of the input value)
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('wq_uuid_1_calendar_picker_header_dynamic_entity').textContent == '12월2015년'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    //Function unitTest
    //Create buy Truong.Luu
    //Create date 22-Feb-2018
    //End unitTest
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
